// Vuosittaiset huoltokustannukset ja arvio ajetuista kilometreistä
$annualCosts=getAnnualCosts($db,(int)$car['id']);
$kmEst=annualKmEstimates(odometerTimelinePoints($db,(int)$car['id']));
$costByYear=[];foreach($annualCosts as $ac)$costByYear[(int)$ac['year']]=(float)$ac['total'];
$yearList=array_unique(array_merge(array_keys($costByYear),array_keys($kmEst['years']??[])));rsort($yearList);
if($yearList):
    $recentYears=array_slice($yearList,0,5);$olderYears=array_slice($yearList,5);
    $yearRow=function(int $y) use($costByYear,$kmEst){
        $cost=$costByYear[$y]??null;$ke=$kmEst['years'][$y]??null;
        $km=$ke?$ke['km']:null;
        $notes=[];if($ke){
            if($ke['project']!==null)$notes[]=t('car.year_pace',['km'=>number_format($ke['project'],0,',',' ')]);
            if($ke['from']!==$y.'-01-01')$notes[]=t('car.readings_from',['date'=>fiDate($ke['from'])]);
            if($ke['to']!==($y+1).'-01-01')$notes[]=t('car.last_reading',['date'=>fiDate($ke['to'])]);
            if($ke['rough'])$notes[]=t('car.rough_estimate');
        }
        $note=implode(' · ',$notes);
        ob_start();?>
        <div class="yearrow"><span class="y"><?=h((string)$y)?></span><strong class="c"><?=$cost!==null?h(money($cost)):'–'?></strong><span class="k"><?=$km!==null?t('car.approx_km',['km'=>h(number_format($km,0,',',' '))]):'–'?><?=$ke&&$ke['partial']?' *':''?></span><?php if($note!==''):?><span class="yn tiny"><?=h($note)?></span><?php endif;?></div>
        <?php return ob_get_clean();
    };
?>
<div class="box" style="margin-top: 14px;">
    <strong><?=t('car.yearly_costs_title')?></strong>
    <div class="yearhead"><span><?=t('car.col_year')?></span><span><?=t('car.col_service_costs')?></span><span><?=t('car.col_driven_est')?></span></div>
    <div style="margin-top: 4px;">
        <?php foreach($recentYears as $yy) echo $yearRow((int)$yy); ?>
        <?php if($olderYears): ?>
            <div id="older-costs-<?= (int)$car['id'] ?>" style="display: none;">
                <?php foreach($olderYears as $yy) echo $yearRow((int)$yy); ?>
