            <button type="button" class="btn2" style="margin-top: 10px; width: 100%;"
                    onclick="document.getElementById('older-costs-<?= (int)$car['id'] ?>').style.display='block'; this.style.display='none';">
                <?=t('car.show_older')?>

            </button>
        <?php endif; ?>
