ear="<?=h(substr((string)$s['service_date'],0,4))?>" <?=$i===0?'open':''?>><summary><div class="service-title"><div><strong><?=h($s['title'])?></strong><?php if(($s['service_type']??'')&&serviceTypeLabel((string)$s['service_type'])!==$s['title']):?> <span class="badge"><?=h(serviceTypeLabel((string)$s['service_type']))?></span><?php endif;?><div class="tiny"><?=h(fiDate($s['service_date']))?> · <?=h(recordedKm((int)$s['odometer']))?><?=$gap['text']?' · '.t('car.since_prev_entry',['text'=>h($gap['text'])]):''?></div></div><span class="badge"><?=t('car.works_count',['n'=>count($s['actions'])+count($s['custom_actions'])])?><?=!empty($s['photos'])?' · 📷 '.count($s['photos']):''?></span></div><div class="chips"><?php foreach($s['actions'] as $a):?><span class="chip"><?=h($a['label'])?></span><?php endforeach;?><?php foreach($s['custom_actions'] as $a):?><span class="chip"><?=h($a['description'])?></span><?php endforeach;?></div></summary><div class="servicebody"><?php foreach($s['actions'] as $a):$q=serviceActionQuantityText($a);?><div class="kv"><span><?=h($a['label'])?></span><span><?=h(implode(' · ',array_filter([serviceActionLabel($a),$q,$a['brand'],$a['supplier_sku'],$a['oem_number'],$a['notes'],serviceIntervalNote($a)])))?><?php if($intervalText=actionIntervalText($a)):?><div class="tiny maintenance-interval"><?=h($intervalText)?></div><?php endif;?></span></div><?php endforeach;?><?php foreach($s['custom_actions'] as $a):?><div class="kv"><span><?=t('car.other_work_row')?></span><span><strong><?=h($a['description'])?></strong><?=$a['notes']?' · '.h($a['notes']):''?></span></div><?php endforeach;?><?php if(!empty($s['inventory_usage'])):?><div class="kv"><span><?=t('car.used_from_stock')?></span><span><?php $iuText=[];foreach($s['inventory_usage'] as $iu)$iuText[]=trim((string)$iu['part_name'].' · '.dec((float)$iu['quantity'],2).' '.unitLabel((string)$iu['unit']).($iu['shelf_snapshot']?' · '.$iu['shelf_snapshot']:''));echo h(implode(' / ',$iuText));?></span></div><?php endif;?><?php if((int)($s['actual_work_seconds']??0)>0):?><div class="kv"><span><?=t('car.actual_work_time')?></span><span><?=h(formatDuration((int)$s['actual_work_seconds']))?></span></div><?php endif;?><?php if(!empty($s['customer_name_snapshot'])):?><div class="kv"><span><?=t('car.customer_at_event')?></span><span><?=h($s['customer_name_snapshot'])?></span></div><?php endif;?><?php if(!empty($s['service_origin'])):?><div class="kv"><span><?=t('car.work_origin')?></span><span><?=h($s['service_origin']==='own'?t('car.origin_own'):($s['service_origin']==='external'?t('car.origin_external'):t('car.origin_legacy')))?></span></div><?php endif;?><?php if(!empty($s['mechanic_name_snapshot'])):?><div class="kv"><span><?=t('car.mechanic')?></span><span><?=h(mechanicLabel($s['mechanic_name_snapshot']))?></span></div><?php endif;?><?php if($s['notes']):?><div class="kv"><span><?=t('car.remarks')?></span><span><?=nl2br(h($s['notes']))?></span></div><?php endif;?><?php if(!empty($s['photos'])):?><div class="kv"><span><?=t('car.service_photos')?></span><div><div class="photo-grid"><?php foreach($s['photos'] as $ph):?><div class="photo-card"><a href="<?=h(photoUrl((int)$ph['id'],'original'))?>" target="_blank"><img loading="lazy" src="<?=h(photoUrl((int)$ph['id'],'thumb'))?>" alt="<?=t('car.photo_alt')?>"></a><?php if(trim((string)($ph['caption']??''))!==''):?><div class="photo-caption"><?=h($ph['caption'])?></div><?php endif;?><div class="photo-tools"><form method="post" class="delete-photo-form"><input type="hidden" name="csrf" value="<?=h(csrf())?>"><input type="hidden" name="action" value="delete_photo"><input type="hidden" name="car_id" value="<?=$carId?>"><input type="hidden" name="photo_id" value="<?=(int)$ph['id']?>"><button class="danger" type="submit"><?=t('car.delete_photo')?></button></form></div></div><?php endforeach;?></div></div></div><?php endif;?><div class="form-actions"><a class="btn2" href="?car=<?=$carId?>&edit_service=<?=(int)$s['id']?>#huolto"><?=t('car.edit')?></a><a class="btn2" target="_blank" href="?print=service&service=<?=(int)$s['id']?>"><?=t('car.print_service')?></a><?php if(!empty($s['photos'])):?><a class="btn2" target="_blank" href="?print=service&service=<?=(int)$s['id']?>&photos=1"><?=t('car.with_photos')?></a><?php endif;?><?php if(invoicingEnabled($app)):?><?php if($sinv):?><a class="btn2" href="?invoice=<?=(int)$sinv['id']?>"><?=t('car.invoice_link',['number'=>h($sinv['invoice_number']),'status'=>h(invoiceStatusLabel((string)$sinv['status']))])?></a><?php else:?><form method="post"><input type="hidden" name="csrf" value="<?=h(csrf())?>"><input type="hidden" name="action" value="create_invoice"><input type="hidden" name="service_id" value="<?=(int)$s['id']?>"><button class="btn2"><?=t('car.create_invoice')?></button></form><?php endif;?><?php endif;?><form method="post" class="delete-service-form" data-delete-label="<?=h($s['title'].' · '.fiDate($s['service_date']).' · '.recordedKm((int)$s['odometer']))?>" data-draft-invoice="<?=h($sinv&&$sinv['status']==='draft'?$sinv['invoice_number']:'')?>"><input type="hidden" name="csrf" value="<?=h(csrf())?>"><input type="hidden" name="action" value="delete_service"><input type="hidden" name="car_id" value="<?=$carId?>"><input type="hidden" name="service_id" value="<?=(int)$s['id']?>"><button class="danger"><?=t('car.delete')?></button></form></div></div></details><?php endforeach;?></div><?php if(count($services)>10):?><button class="btn2 history-more" type="button" id="historyMore"><?=t('car.show_older_services',['n'=>count($services)-10])?></button><?php endif;endif;?></section>

